#[path = "/tmp/ref/old_token.rs"]
mod old;

fn all(line: &str) -> Vec<Result<String, logscan::LexError>> {
    logscan::tokenize(line).map(|r| r.map(|t| format!("{t:?}"))).collect()
}
fn all_old(line: &str) -> Vec<Result<String, logscan::LexError>> {
    old::tokenize(line).map(|r| r.map(|t| format!("{t:?}"))).collect()
}

#[test]
fn same_as_old() {
    let alpha = [b'a', b' ', b'\t', b'[', b']', b'"', b'=', b'\\', b'n', b'x'];
    let mut count = 0u64;
    for len in 0..=8u32 {
        let total = (alpha.len() as u64).pow(len);
        for mut k in 0..total {
            let mut s = Vec::new();
            for _ in 0..len { s.push(alpha[(k % alpha.len() as u64) as usize]); k /= alpha.len() as u64; }
            let s = String::from_utf8(s).unwrap();
            assert_eq!(all(&s), all_old(&s), "line {s:?}");
            count += 1;
        }
    }
    println!("{count} lines");
}
