                    None => return Err(LexError::UnterminatedQuote { pos: open }),
                    Some(b'"' | b'\\' | b'n' | b't') => close += 2,
                    Some(_) => return Err(LexError::InvalidEscape { pos: close }),
                },
                Some(_) => close += 1,
            }
        }
        self.finish_delimited(close)?;
        Ok(Token::Quoted(&self.src[start..close]))
    }

    /// Index of the first byte from `start` for which `is_end` holds, or the end of the line.
    /// A `"` before that point is an error.
    fn unquoted_end(&self, start: usize, is_end: impl Fn(u8) -> bool) -> Result<usize, LexError> {
        let bytes = self.src.as_bytes();
        let mut end = start;
        while end < bytes.len() && !is_end(bytes[end]) {
            if bytes[end] == b'"' {
                return Err(LexError::UnexpectedQuote { pos: end });
            }
            end += 1;
        }
        Ok(end)
    }

    /// Moves past the closing delimiter at `close`, which must be followed by a blank or the end of the line.
    fn finish_delimited(&mut self, close: usize) -> Result<(), LexError> {
        let after = close + 1;
        match self.src.as_bytes().get(after) {
            Some(&byte) if !is_blank(byte) => Err(LexError::ExpectedSeparator { pos: after }),
            _ => {
                self.pos = after;
                Ok(())
            }
        }
    }
}

