use crate::error::LexError;

/// One piece of a log line, borrowed from the line itself.
#[derive(Debug, Clone, Copy, PartialEq, Eq)]
pub enum Token<'a> {
    /// The text between `[` and `]`.
    Timestamp(&'a str),
    /// The name in front of `=`.
    Key(&'a str),
    /// A double-quoted value without its quotes, escapes left as written.
    Quoted(&'a str),
    /// An unquoted value; empty for `key=` followed by a space or the end of the line.
    Bare(&'a str),
    /// A run of characters that is neither a timestamp nor part of a pair.
    Word(&'a str),
}

/// Where the tokenizer is in the `key=value` grammar.
#[derive(Debug, Clone, Copy, PartialEq, Eq)]
enum State {
    /// Expecting a timestamp, key or word.
    Field,
    /// Just consumed a key and its `=`; expecting that key's value.
    Value,
    /// An error was reported; nothing more is yielded.
    Failed,
}

/// Streams the tokens of one line. After the first error it yields nothing more.
#[derive(Debug, Clone)]
pub struct Tokens<'a> {
    src: &'a str,
    pos: usize,
    state: State,
}

impl<'a> Tokens<'a> {
    pub fn new(src: &'a str) -> Self {
        Tokens { src, pos: 0, state: State::Field }
    }
}

/// Tokenizes one log line without copying any of it.
pub fn tokenize(line: &str) -> Tokens<'_> {
    Tokens::new(line)
}

fn is_blank(byte: u8) -> bool {
    byte == b' ' || byte == b'\t'
}

impl<'a> Iterator for Tokens<'a> {
    type Item = Result<Token<'a>, LexError>;

    fn next(&mut self) -> Option<Self::Item> {
        let item = match self.state {
            State::Field => self.next_field()?,
            State::Value => self.next_value(),
            State::Failed => return None,
        };
        if item.is_err() {
            self.fail();
        }
        Some(item)
    }
}

// The scanners below are the hot path of the import: they work on bytes and
// allocate nothing. Each one moves `pos` and `state` only when it succeeds;
// `next` parks the tokenizer after an error.
impl<'a> Tokens<'a> {
    fn fail(&mut self) {
        self.state = State::Failed;
        self.pos = self.src.len();
    }

    fn next_field(&mut self) -> Option<Result<Token<'a>, LexError>> {
        let bytes = self.src.as_bytes();
        let start = self.skip_blanks();
        self.pos = start;
        if start >= bytes.len() {
            return None;
        }
        Some(match bytes[start] {
            b'[' => self.timestamp(start),
            b'"' => Err(LexError::UnexpectedQuote { pos: start }),
            b'=' => Err(LexError::EmptyKey { pos: start }),
            _ => self.key_or_word(start),
        })
    }

    fn next_value(&mut self) -> Result<Token<'a>, LexError> {
        let start = self.pos;
        self.state = State::Field;
        if self.src.as_bytes().get(start) == Some(&b'"') {
            self.quoted(start)
        } else {
            self.bare(start)
        }
    }

    fn skip_blanks(&self) -> usize {
        let bytes = self.src.as_bytes();
        let mut pos = self.pos;
        while pos < bytes.len() && is_blank(bytes[pos]) {
            pos += 1;
        }
        pos
    }

    /// `[` at `open`, then everything up to the closing `]`.
    fn timestamp(&mut self, open: usize) -> Result<Token<'a>, LexError> {
        let bytes = self.src.as_bytes();
        let start = open + 1;
        let mut close = start;
        loop {
            match bytes.get(close) {
                None => return Err(LexError::UnterminatedTimestamp { pos: open }),
                Some(b']') => break,
                Some(b'[') => return Err(LexError::NestedBracket { pos: close }),
                Some(_) => close += 1,
            }
        }
        self.finish_delimited(close)?;
        Ok(Token::Timestamp(&self.src[start..close]))
    }

    /// A run of text that is a key if `=` ends it, and a word otherwise.
    fn key_or_word(&mut self, start: usize) -> Result<Token<'a>, LexError> {
        let end = self.unquoted_end(start, |byte| is_blank(byte) || byte == b'=')?;
        if self.src.as_bytes().get(end) == Some(&b'=') {
            self.state = State::Value;
            self.pos = end + 1;
            Ok(Token::Key(&self.src[start..end]))
        } else {
            self.pos = end;
            Ok(Token::Word(&self.src[start..end]))
        }
    }

    /// A value without quotes; empty when `start` is a blank or the end of the line.
    fn bare(&mut self, start: usize) -> Result<Token<'a>, LexError> {
        let end = self.unquoted_end(start, is_blank)?;
        self.pos = end;
        Ok(Token::Bare(&self.src[start..end]))
    }

    /// `"` at `open`, then everything up to the closing `"`, escapes left as written.
    fn quoted(&mut self, open: usize) -> Result<Token<'a>, LexError> {
        let bytes = self.src.as_bytes();
        let start = open + 1;
        let mut close = start;
        loop {
            match bytes.get(close) {
                None => return Err(LexError::UnterminatedQuote { pos: open }),
                Some(b'"') => break,
                Some(b'\\') => match bytes.get(close + 1) {
                    None => return Err(LexError::UnterminatedQuote { pos: open }),
                    Some(b'"' | b'\\' | b'n' | b't') => close += 2,
                    Some(_) => return Err(LexError::InvalidEscape { pos: close }),
                },
                Some(_) => close += 1,
            }
        }
        self.finish_delimited(close)?;
        Ok(Token::Quoted(&self.src[start..close]))
    }

    /// Index of the first byte from `start` for which `is_end` holds, or the end of the line.
    /// A `"` before that point is an error.
    fn unquoted_end(&self, start: usize, is_end: impl Fn(u8) -> bool) -> Result<usize, LexError> {
        let bytes = self.src.as_bytes();
        let mut end = start;
        while end < bytes.len() && !is_end(bytes[end]) {
            if bytes[end] == b'"' {
                return Err(LexError::UnexpectedQuote { pos: end });
            }
            end += 1;
        }
        Ok(end)
    }

    /// Moves past the closing delimiter at `close`, which must be followed by a blank or the end of the line.
    fn finish_delimited(&mut self, close: usize) -> Result<(), LexError> {
        let after = close + 1;
        match self.src.as_bytes().get(after) {
            Some(&byte) if !is_blank(byte) => Err(LexError::ExpectedSeparator { pos: after }),
            _ => {
                self.pos = after;
                Ok(())
            }
        }
    }
}

